@push('scripts')
<script src="https://cdn.jsdelivr.net/npm/axios@1.11.0/dist/axios.min.js"></script>
<script>
const watchToast=message=>{const toast=document.createElement('div');toast.className='alert success-alert';toast.innerHTML='<i class="fas fa-check-circle"></i><span>'+message+'</span>';document.querySelector('.content')?.prepend(toast);setTimeout(()=>toast.remove(),3000)};document.querySelectorAll('[data-watch-add]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button'),original=button.innerHTML;button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin"></i> Saving';try{const response=await axios.post(form.action,{}, {headers:{'X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'}});button.innerHTML='<i class="fas fa-check"></i> Monitoring';watchToast(response.data.message)}catch(error){button.disabled=false;button.innerHTML=original;alert(error.response?.data?.message||'Unable to update watchlist.')}}));document.querySelectorAll('[data-watch-remove]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();if(!confirm('Remove this country from monitoring?'))return;const button=form.querySelector('button');button.disabled=true;try{const response=await axios.delete(form.action,{headers:{'X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'}});const card=form.closest('[data-watch-card]');card.style.opacity='0';setTimeout(()=>card.remove(),220);watchToast(response.data.message)}catch(error){button.disabled=false;alert(error.response?.data?.message||'Unable to update watchlist.')}}));
</script>
@endpush
